const float BPM = 175.0;
vec3 lightDir = vec3(1.0,1.,1.);
const float PI = 3.1415926;
float bt;
        float bf;
        float ff;
        float cnt;


vec3 hash(vec3 p){
  uvec3 t = floatBitsToUint(p);
  uint n = 1258365938u;
  t = ((t<<8U) + n) * t.yzx;
  t = ((t<<8U) + n) * t.yzx;
  t = ((t<<8U) + n) * t.yzx;
  return vec3(t) / float(0xffffffffu);
  }

mat2 rot(float t){
  return mat2(cos(t),-sin(t),sin(t),cos(t));
  }

float dfSphere(vec3 p,float s)
{
  return length(p) - s;
  }

  float dfBox(vec3 p,vec3 size){
    p = abs(p)-size;
    return max(max(p.x,p.y),p.z);
    }

    float crossbox(vec3 p,vec3 size)
    {
      vec3 f = vec3(1./3.,1./3.,4./3.);
      float d1 = dfBox(p,size * f.xyz);
      float d2 = dfBox(p,size * f.zxy);
      float d3 = dfBox(p,size * f.yzx);
      return min(min(d1,d2),d3);
    }

    float menger(vec3 p)
    {
      vec3 size = vec3(0.75);
      float d = dfBox(p,size);
      float cd = crossbox(p,size);
      d = max(d,-cd);
      for(int i = 0; i<2;i++){
      size *= 1./3.;
      float m = size.x * 2.;
      p = mod(p - 0.5 * m,m)-0.5 * m;
      cd = crossbox(p,size);
      d = max(d,-cd);
      }

      return d;
    }

float map(vec3 p)
{
  //p.x += 7.5;
  p.xz = mod(p.xz,3.)-1.5;
  //p.z += 0.1;
 p.xz *=rot(bf-ff);
  //p.xz = mod(p.xz-0.5*3.0,7.0) - 0.5*3.0;
  p.xy *= rot(iTime);
  p.yz *= rot(iTime);
  float d1 = menger(p);

  return d1;
}


vec3 normal(vec3 p)
{
  vec3 d = vec3(0.001,0.,0.);
  return normalize(vec3(map(p+d.xyz) - map(p-d.xyz),
                        map(p+d.yxz) - map(p-d.yxz),
                        map(p+d.zyx) - map(p-d.zyx)));
  }

  void uvfold(inout vec2 uv){
    int n = 12;
    for(int i = 0;i < n;i++){
      float btu = bt + float(i);
      float bfu = floor(btu);
      float ffu = fract(btu);
      ffu = smoothstep(0.,1.,pow(ffu,0.3));
    vec3 s = hash(vec3(29.383,83.4874092,bfu));
      float ins = ((i==0)?1.0 - ffu:(i == n-1)?ffu:1.);
      vec3 v = hash(vec3(s*12.4837)) * ins;
      if(s.x<0.6){
        float a = PI * v.x * .5;
        vec2 of = v.yz;
        vec2 p = vec2(cos(a),sin(a));
        uv -= of;
        uv -= 2.0 * min(0.,dot(p,uv)) * p;
        uv += of;
        }
        else{
          //uv *= s.z + 1.0;
          }

    }
    }



    void setTime(){
      bt = iTime * BPM / 60.0;
      bf = floor(bt);
      ff = fract(bt);
      ff = smoothstep(0.,1.,pow(ff,0.3));
      cnt = mod(bf,4.);
      }

void mainImage(out vec4 fragColor, in vec2 fragCoord )
{
	vec2 uv = (fragCoord.xy* 2.0 - iResolution.xy) / min(iResolution.x,iResolution.y);
	vec3 col = vec3(0.0);

  setTime();
  //uvfold(uv);
  uv *= rot((-bf - ff) * 0.2);
  vec3 cp = vec3(0.0,0.0,3.0 - bf - ff);
  vec3 cu = vec3(0.0,1.0,0.0);
  vec3 cd = vec3(0.,0.,-1.0);
  vec3 cs = cross(cu,cd);
  float td = 1.0;

  vec3 ray = normalize(cs * uv.x + cu * uv.y + cd * td);

  vec3 rp = cp;
  float deff,ra,ca = 0.0;

  for(int i = 0;i < 150;i++){
    rp.xy *= rot(rp.z * 0.5);
    //rp.xy *= rot(cnt * ff);
    deff = map(rp);

    if(abs(deff) < 0.001){
      vec3 rNormal = normal(rp);
      float lightPow = clamp(dot(rNormal,lightDir),0.2,1.0);
      col = vec3(mix(rNormal,vec3(lightPow),rp.z));
      break;
      }

    /*
    deff = max(abs(deff),0.02);
    ca += abs(exp(-deff * 3.0)* 2.);
    ra += deff * 0.5;
    */
     ra += deff;
    rp = cp + ray * ra;

    }
  //col = vec3(0.6,0.5,cnt) * vec3(ca * 0.01);
	fragColor = vec4(col,1.0);
}
